# LBDS Animated Props — RPG Maker XP / La Base de Sky v21.1 (dev)
# Reads Data/AnimatedProps/objects.json generated by the Maker Studio mod.
# Keeps animations external to native tiles and does NOT patch rxdata files.
# This file is loaded by the regular Essentials PluginManager.
require 'json'

module LBDSAnimatedProps
  DATA_FILE = 'Data/AnimatedProps/objects.json'
  ART_DIR = 'Graphics/AnimatedProps/'
  CELL_SIZE = 32
  module_function

  def data
    return @data if @data
    @data = { 'definitions' => [], 'placements' => {} }
    return @data unless File.file?(DATA_FILE)
    candidate = JSON.parse(File.binread(DATA_FILE))
    unless candidate.is_a?(Hash) && candidate['schema'] == 1
      warn 'LBDS Animated Props: formato de objects.json no soportado.'
      return @data
    end
    @data = candidate
  rescue StandardError => e
    warn "LBDS Animated Props: #{e.class}: #{e.message}"
    @data
  end

  def clear_cache!
    @data = nil
  end

  def valid_sheet?(sheet)
    sheet.is_a?(String) && sheet.match?(/\A[\p{L}\p{N}_() .-]+\.png\z/i)
  end

  def map_placements(map_id)
    items = data.fetch('placements', {})[map_id.to_i.to_s]
    return [] unless items.is_a?(Array)
    defs = (data['definitions'] || []).each_with_object({}) do |d, memo|
      memo[d['id']] = d if d.is_a?(Hash) && d['id'].is_a?(String)
    end
    items.filter_map do |p|
      next unless p.is_a?(Hash)
      definition = defs[p['defId']]
      next unless definition && valid_sheet?(definition['sheet'])
      w, h = definition['width'].to_i, definition['height'].to_i
      f, fps = definition['frames'].to_i, definition['fps'].to_i
      next unless (1..32).cover?(w) && (1..32).cover?(h)
      next unless (1..64).cover?(f) && (1..60).cover?(fps)
      next unless p['x'].is_a?(Integer) && p['y'].is_a?(Integer)
      next if p['x'] < 0 || p['y'] < 0
      cells = definition['cells']
      next unless cells.is_a?(Array) && cells.length == w * h
      { x: p['x'], y: p['y'], width: w, height: h, frames: f, fps: fps,
        sheet: definition['sheet'], cells: cells, id: definition['id'],
        loop: definition['loop'] != false }
    end
  end

  # Picks the last placed cell. Like the uppermost tile layer, the most recent
  # object takes precedence where two object's footprints overlap.
  def cell_at(map, x, y)
    return nil unless map.respond_to?(:lbds_props_lookup)
    map.lbds_props_lookup[[x, y]]
  end

  def blocking?(map, x, y, direction)
    c = cell_at(map, x, y)
    return false unless c
    passage = c.fetch('passage', 0).to_i & 0x0f
    bit = { 2 => 1, 4 => 2, 6 => 4, 8 => 8 }[direction]
    return passage != 0 if bit.nil?
    (passage & bit) != 0
  end

  def movement_blocked?(map, x, y, direction)
    delta = { 2 => [0, 1, 8], 4 => [-1, 0, 6],
              6 => [1, 0, 4], 8 => [0, -1, 2] }[direction]
    return false unless delta
    dx, dy, opposite = delta
    blocking?(map, x, y, direction) || blocking?(map, x + dx, y + dy, opposite)
  end
end

module LBDSAnimatedPropsMap
  attr_reader :lbds_props_lookup, :lbds_props_placements

  def setup(map_id)
    super
    lbds_props_rebuild
  end

  def lbds_props_rebuild
    @lbds_props_placements = LBDSAnimatedProps.map_placements(@map_id)
    @lbds_props_lookup = {}
    @lbds_props_placements.each do |p|
      p[:height].times do |y|
        p[:width].times do |x|
          next unless valid?(p[:x] + x, p[:y] + y)
          cell = p[:cells][y * p[:width] + x]
          @lbds_props_lookup[[p[:x] + x, p[:y] + y]] = cell if cell.is_a?(Hash)
        end
      end
    end
  end

  def passable?(x, y, dir, self_event = nil)
    return false if LBDSAnimatedProps.movement_blocked?(self, x, y, dir)
    super
  end

  def passableStrict?(x, y, dir, self_event = nil)
    return false if LBDSAnimatedProps.movement_blocked?(self, x, y, dir)
    super
  end

  def terrain_tag(x, y, countBridge = false)
    cell = LBDSAnimatedProps.cell_at(self, x, y)
    if cell && cell.fetch('terrainTag', 0).to_i > 0
      tag = GameData::TerrainTag.try_get(cell['terrainTag'].to_i)
      return tag if tag
    end
    super
  end

  def bush?(x, y)
    c = LBDSAnimatedProps.cell_at(self, x, y)
    return true if c && (c.fetch('passage', 0).to_i & 0x40) != 0
    super
  end

  def counter?(x, y)
    c = LBDSAnimatedProps.cell_at(self, x, y)
    return true if c && (c.fetch('passage', 0).to_i & 0x80) != 0
    super
  end
end

# One short sprite per contiguous group of cells of equal priority. The entire
# object advances frames together; split rows allow tile-like draw priority.
module LBDSAnimatedPropsSpriteset
  def initialize(map = nil)
    super
    @lbds_prop_sprites = []
    @lbds_prop_bitmaps = {}
    @lbds_prop_started_at = System.uptime
    lbds_props_build_sprites
    lbds_props_update_sprites
  end

  def lbds_props_build_sprites
    return unless @map
    placements = @map.lbds_props_placements || []
    placements.each do |p|
      sheet = p[:sheet]
      bitmap = @lbds_prop_bitmaps[sheet]
      unless bitmap
        begin
          bitmap = Bitmap.new(LBDSAnimatedProps::ART_DIR + sheet)
          @lbds_prop_bitmaps[sheet] = bitmap
        rescue StandardError => e
          warn "LBDS Animated Props: no se pudo cargar #{sheet}: #{e.message}"
          next
        end
      end
      expected_width = p[:width] * LBDSAnimatedProps::CELL_SIZE * p[:frames]
      expected_height = p[:height] * LBDSAnimatedProps::CELL_SIZE
      if bitmap.width < expected_width || bitmap.height < expected_height
        warn "LBDS Animated Props: dimensiones incorrectas en #{sheet}; se esperan #{expected_width}x#{expected_height}."
        next
      end
      p[:height].times do |cy|
        cx = 0
        while cx < p[:width]
          cell = p[:cells][cy * p[:width] + cx]
          priority = [[cell.fetch('priority', 0).to_i, 0].max, 5].min
          run = 1
          while cx + run < p[:width]
            c = p[:cells][cy * p[:width] + cx + run]
            break if [[c.fetch('priority', 0).to_i, 0].max, 5].min != priority
            run += 1
          end
          sprite = Sprite.new(Spriteset_Map.viewport)
          sprite.bitmap = bitmap
          sprite.src_rect.set(cx * 32, cy * 32, run * 32, 32)
          sprite.zoom_x = TilemapRenderer::ZOOM_X
          sprite.zoom_y = TilemapRenderer::ZOOM_Y
          @lbds_prop_sprites << [sprite, p, cx, cy, run, priority, -1]
          cx += run
        end
      end
    end
  end

  def lbds_props_update_sprites
    return unless @map && @lbds_prop_sprites
    mx = (@map.display_x.to_f / Game_Map::X_SUBPIXELS).round
    my = (@map.display_y.to_f / Game_Map::Y_SUBPIXELS).round
    time = System.uptime - @lbds_prop_started_at
    pause_anim = $PokemonSystem && $PokemonSystem.respond_to?(:autotile_animations) &&
                 $PokemonSystem.autotile_animations == 1
    @lbds_prop_sprites.each do |entry|
      s, p, cx, cy, run, priority, old_frame = entry
      elapsed_frames = (time * p[:fps]).floor
      frame = pause_anim ? 0 : (p[:loop] ? elapsed_frames % p[:frames] : [elapsed_frames, p[:frames] - 1].min)
      if frame != old_frame
        s.src_rect.set(frame * p[:width] * 32 + cx * 32, cy * 32, run * 32, 32)
        entry[6] = frame
      end
      sx = (p[:x] + cx) * Game_Map::TILE_WIDTH - mx
      sy = (p[:y] + cy) * Game_Map::TILE_HEIGHT - my
      if TilemapRenderer::ZOOM_X != 1
        sx = (sx - Graphics.width / 2) * TilemapRenderer::ZOOM_X + Graphics.width / 2
      end
      if TilemapRenderer::ZOOM_Y != 1
        sy = (sy - Graphics.height / 2) * TilemapRenderer::ZOOM_Y + Graphics.height / 2
      end
      s.x = sx.round
      s.y = sy.round
      # Native tile priority=0 is drawn below all characters (z=0).
      s.z = priority == 0 ? 0 : sy.round + Game_Map::TILE_HEIGHT * (priority + 1) + 1
      s.visible = (sx + run * Game_Map::TILE_WIDTH > 0 && sy + Game_Map::TILE_HEIGHT > 0 &&
                   sx < Graphics.width && sy < Graphics.height)
    end
  end

  def update
    super
    lbds_props_update_sprites
  end

  def dispose
    if @lbds_prop_sprites
      @lbds_prop_sprites.each { |item| item[0].dispose unless item[0].disposed? }
      @lbds_prop_sprites.clear
    end
    if @lbds_prop_bitmaps
      @lbds_prop_bitmaps.each_value { |bmp| bmp.dispose unless bmp.disposed? }
      @lbds_prop_bitmaps.clear
    end
    super
  end
end

Game_Map.prepend(LBDSAnimatedPropsMap)
Spriteset_Map.prepend(LBDSAnimatedPropsSpriteset)
